# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: digest
def digest(xs, factor=10):
    return [v * factor for v in xs]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs, factor=10):
    return [v * factor for v in xs[1:]]

# region: fold
def fold(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return intake(fold(emit(shape(digest(render(raw))))))

